#include <vector>
#include <numeric>

using namespace std;

class Solution {
public:
    int minMoves(vector<int>& nums, int k) {
        vector<int> pos;
        for (int i = 0; i < nums.size(); ++i)
            if (nums[i]) pos.push_back(i - pos.size());
        vector<long long> prefix(pos.size() + 1);
        for (int i = 0; i < pos.size(); ++i)
            prefix[i + 1] = prefix[i] + pos[i];

        long long res = LLONG_MAX;
        for (int i = 0; i + k <= pos.size(); ++i) {
            int mid = i + k / 2;
            long long left = prefix[mid] - prefix[i];
            long long right = prefix[i + k] - prefix[mid + 1];
            res = min(res, right - left + (k % 2 ? 0 : pos[mid]));
        }
        return res;
    }
};
